<script lang="ts">
 import{onMount,tick}from'svelte';import type{SkinSession}from'./skins/session.js';import type{SkinPackage,Orientation}from'./skins/types.js';import{catalogPage,loadCatalog,thumbnailUrl,type SkinCatalog,type CatalogEntry}from'./skins/catalog.js';import{boundedFetch}from'./skins/network.js';import{skinLimits}from'./skins/types.js';import SkinPreview from'./SkinPreview.svelte';
 let{session,disabled=false}:{session:SkinSession;disabled?:boolean}=$props();
 let revision=$state(0),dialog=$state<HTMLDialogElement>(),catalog=$state<SkinCatalog|null>(null),catalogBusy=$state(false),catalogError=$state<string|null>(null),catalogNote=$state<string|null>(null),catalogTab=$state(false),query=$state(''),system=$state(''),format=$state('delta'),page=$state(0),removeId=$state<string|null>(null),downloadEntry=$state<CatalogEntry|null>(null),failedImages=$state<Record<string,boolean>>({});
 const s=$derived.by(()=>{revision;return{...session};});const results=$derived(catalogPage(catalog??{entries:[],dropped:0},query,system,format,page));let catalogAbort:AbortController|null=null;
 onMount(()=>{system=session.system;const unsub=session.subscribe(()=>revision++);return()=>{unsub();catalogAbort?.abort();session.dispose();};});
 async function act(fn:()=>void|Promise<void>){try{await fn();}catch(e){session.fail(e);}}
 async function show(){session.open();await tick();dialog?.showModal();}
 function close(){catalogAbort?.abort();catalogBusy=false;session.close();dialog?.close();}
 async function browse(force=false){catalogTab=true;if(catalog&&!force)return;catalogAbort?.abort();const abort=new AbortController();catalogAbort=abort;catalogBusy=true;catalogError=null;try{const result=await loadCatalog(session.library,force,abort.signal);if(abort.signal.aborted)return;catalog=result.catalog;catalogNote=result.warning??(result.catalog.dropped?`${result.catalog.dropped} malformed catalog entries were skipped.`:null);}catch(e){if(!abort.signal.aborted)catalogError=e instanceof Error?e.message:'Catalog unavailable';}finally{if(catalogAbort===abort)catalogBusy=false;}}
 function files(file:File|undefined){if(!file)return;downloadEntry=null;void act(()=>session.import(file));}
 async function downloaded(entry:CatalogEntry){downloadEntry=entry;catalogAbort?.abort();const abort=new AbortController();catalogAbort=abort;catalogBusy=true;catalogError=null;try{const bytes=await boundedFetch(entry.downloadURL,skinLimits.archive,abort.signal);abort.signal.throwIfAborted();if(catalogAbort!==abort||!session.presentationOpen)return;await session.import(new Blob([Uint8Array.from(bytes).buffer]));}catch(e){if(!abort.signal.aborted)catalogError='This provider could not be fetched here. Download its file, then choose Import .deltaskin.';}finally{if(catalogAbort===abort)catalogBusy=false;}}
 async function chosen(pkg:SkinPackage){downloadEntry=null;await act(()=>session.preview(pkg,{}));}
 async function apply(){await act(async()=>{await session.apply();dialog?.close();});}
 async function variant(key:string){if(session.previewPackage)await act(()=>session.preview(session.previewPackage!,{...session.previewChoices,[session.previewOrientation]:key},session.previewOrientation));}
 async function orientation(value:Orientation){if(session.previewPackage)await act(()=>session.preview(session.previewPackage!,session.previewChoices,value));}
 const inputFile=(e:Event)=>{const target=e.currentTarget as HTMLInputElement;files(target.files?.[0]);target.value='';};
</script>
<section class="skin-controls" aria-label="Skins">
 <h2>Skins</h2><p class="dim">Procedural controls and imported artwork share one layout editor.</p>
 <div class="player-controls"><button type="button" disabled={disabled||s.busy} onclick={show}>Import or browse skins</button><button type="button" disabled={disabled||s.busy||!s.input.ready} onclick={()=>act(()=>session.resetOriginal())}>Reset skin edits</button></div>
 {#if !s.presentationOpen}<p role="status">{s.message}</p>{/if}{#if s.error&&!s.presentationOpen}<p role="alert" class="problem">{s.error}</p>{/if}
 <dialog bind:this={dialog} class="skin-dialog" aria-label="Skin library" oncancel={e=>{e.preventDefault();close();}} onclose={()=>{if(session.presentationOpen)session.close();}}>
 <div class="skin-dialog-head"><div><h2>Skins for your player</h2><p class="dim">Browse, inspect, then apply. The game continues running with mapped controls released.</p></div><button type="button" onclick={close}>Close skins</button></div>
 <div class="skin-toolbar"><label class="skin-file">Import .deltaskin<input aria-label="Import .deltaskin" type="file" accept=".deltaskin,.zip" disabled={s.busy||catalogBusy} onchange={inputFile}/></label><button type="button" onclick={()=>catalogTab=false}>My skins</button><button type="button" onclick={()=>browse()}>Browse emuskins</button></div>
 <div class="skin-dialog-body"><div>
 {#if catalogTab}
 <div class="skin-filters"><label>Search skins<input aria-label="Search skins" bind:value={query} oninput={()=>page=0}/></label><label>System<select aria-label="Skin system" bind:value={system} onchange={()=>page=0}><option value="">All systems</option>{#each [...new Set([session.system,...(catalog?.entries??[]).flatMap(e=>e.systems)])].sort() as name}<option value={name}>{name.toUpperCase()}</option>{/each}</select></label><label>Format<select aria-label="Skin format" bind:value={format} onchange={()=>page=0}><option value="delta">Delta skins</option><option value="all">All formats</option></select></label></div>
 <button type="button" disabled={catalogBusy} onclick={()=>browse(true)}>Refresh catalog</button>
 {#if catalogBusy}<p role="status">Loading skin catalog or download…</p>{/if}{#if catalogNote}<p role="status">{catalogNote}</p>{/if}{#if catalogError}<p role="alert">{catalogError}</p>{/if}
 {#if downloadEntry}<p><a href={downloadEntry.downloadURL} target="_blank" rel="noopener noreferrer">Download {downloadEntry.name} from its provider</a>, then use Import .deltaskin.</p>{/if}
 <p>{results.total} skins · page {results.page+1} of {results.pages}</p><div class="skin-cards">{#each results.items as entry(entry.id)}{@const thumb=thumbnailUrl(entry)}<article class="skin-card">{#if thumb&&!failedImages[entry.id]}<img src={thumb} crossorigin="anonymous" referrerpolicy="no-referrer" loading="lazy" alt={entry.name+' preview'} onerror={()=>failedImages={...failedImages,[entry.id]:true}}/>{:else}<div class="skin-placeholder">Preview unavailable</div>{/if}<h3>{entry.name}</h3><p class="dim">{entry.author} · {entry.systems.join(', ')}</p><button type="button" disabled={s.busy||catalogBusy||entry.format!=='delta'} onclick={()=>act(()=>downloaded(entry))}>{entry.format==='delta'?'Inspect download':'Unsupported format'}</button><a href={entry.downloadURL} target="_blank" rel="noopener noreferrer">Provider</a></article>{/each}</div>
 <div class="player-controls"><button type="button" disabled={results.page===0} onclick={()=>page=results.page-1}>Previous skins</button><button type="button" disabled={results.page+1===results.pages} onclick={()=>page=results.page+1}>Next skins</button></div>
 {:else}
 <h3>Built-in layouts</h3><div class="player-controls"><button type="button" disabled={disabled||s.busy||!s.input.ready} onclick={()=>act(async()=>{await session.useBuiltin('compact');close();})}>Use compact controls</button><button type="button" disabled={disabled||s.busy||!s.input.ready} onclick={()=>act(async()=>{await session.useBuiltin('standard');close();})}>Use standard controls</button></div>
 <h3>Installed in this browser</h3>{#if !s.items.length}<p class="dim">Import a package and choose Keep in library to make it available here.</p>{/if}
 {#each s.items as pkg(pkg.id)}<article class="skin-installed"><button type="button" disabled={s.busy} onclick={()=>chosen(pkg)}>{pkg.name} · {pkg.system.toUpperCase()}</button><button type="button" disabled={s.busy} aria-label={'Remove '+pkg.name} onclick={()=>removeId=pkg.id}>Remove</button>{#if removeId===pkg.id}<p>Remove this local skin? If it is active, procedural controls will replace it.</p><button type="button" onclick={()=>act(async()=>{await session.remove(pkg.id);removeId=null;})}>Confirm removal</button><button type="button" onclick={()=>removeId=null}>Keep skin</button>{/if}</article>{/each}
 <div class="skin-drop" role="region" aria-label="Drop a skin file" ondragover={e=>e.preventDefault()} ondrop={e=>{e.preventDefault();if(!s.busy)files(e.dataTransfer?.files[0]);}}>Choose a file from iPhone Files, or drop one here on Mac.</div>
 {/if}
 </div><aside class="skin-inspect" aria-label="Skin inspection">
 {#if s.busy}<p role="status">Inspecting or preparing artwork… {s.progress}%</p><button type="button" onclick={()=>session.cancel()}>Cancel skin operation</button>{/if}
 {#if s.previewPackage&&s.previewLayout}<h3>{s.previewPackage.name}</h3><p class="dim">{s.previewPackage.author||'Author not provided'} · {s.previewPackage.system.toUpperCase()}</p><SkinPreview layout={s.previewLayout} orientation={s.previewOrientation} assets={s.previewAssets}/>
 <label>Preview orientation<select aria-label="Preview orientation" value={s.previewOrientation} disabled={s.busy} onchange={e=>orientation(e.currentTarget.value as Orientation)}><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select></label>
 <label>Representation<select aria-label="Skin representation" value={s.previewChoices[s.previewOrientation]??s.previewPackage.variants.find(v=>v.orientation===s.previewOrientation)?.key??''} disabled={s.busy} onchange={e=>variant(e.currentTarget.value)}>{#each s.previewPackage.variants.filter(v=>v.orientation===s.previewOrientation) as v(v.key)}<option value={v.key}>{v.device} · {v.display}</option>{/each}</select></label>
 <p>{s.previewLive?'Compatible with this game’s layout':'Preview only for this player'}</p>{#each s.previewIssues as issue}<p class="dim">{issue}</p>{/each}
 <div class="player-controls"><button type="button" disabled={disabled||s.busy||!s.previewLive||!s.input.ready} onclick={apply}>Apply skin for session</button><button type="button" disabled={s.busy} onclick={()=>act(()=>session.install())}>Keep in library</button><button type="button" disabled={s.busy} onclick={()=>session.cancel()}>Cancel preview</button></div>
 {:else}<p class="dim">Select or import a skin to inspect its artwork, controls and compatibility before applying.</p>{/if}
 </aside></div>
 {#if s.error}<p role="alert" class="problem">{s.error}</p>{/if}
 <p role="status">{s.message}</p><div class="skin-dialog-foot"><button type="button" disabled={disabled||s.busy||!s.input.ready||!!s.input.draft} onclick={()=>act(()=>session.remember('core',true))}>Remember skin for this core</button>{#if session.game}<button type="button" disabled={disabled||s.busy||!s.input.ready||!!s.input.draft} onclick={()=>act(()=>session.remember('game',true))}>Remember skin for this game</button>{/if}<p class="dim">Local to this browser and exact build. Original imports stay intact; layout edits are separate. <a href="/ui/third-party-skins.txt" target="_blank" rel="noopener noreferrer">Open-source notices</a></p></div>
 </dialog>
</section>
